import React from "react";
import { useNavigate } from "react-router-dom";

export default function LiveDemoPage() {
  const navigate = useNavigate();

  const feeds = [
    { label: "🎥 RGB Feed", color: "border-cyan-500", fake: "/rgb-feed.gif" },
    { label: "🔥 Thermal View", color: "border-orange-400", fake: "/thermal-feed.gif" },
    { label: "🧠 Depth Map", color: "border-purple-400", fake: "/depth-map.gif" },
    { label: "🗺️ GPS Zone", color: "border-green-400", fake: "/gps-map.gif" },
  ];

  return (
    <div className="min-h-screen bg-black text-white p-10 font-sans">
      {/* Header */}
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl text-cyan-400 font-bold tracking-wide animate-pulse">ADI Drone — Live Surveillance</h1>
        <button onClick={() => navigate("/")} className="text-cyan-200 hover:text-white border border-cyan-500 px-4 py-1 rounded-lg transition-all">
          ⬅ Back Home
        </button>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {feeds.map((feed, idx) => (
          <div
            key={idx}
            className={`bg-gray-900 rounded-xl border-2 ${feed.color} p-3 overflow-hidden hover:scale-[1.02] hover:shadow-lg transition-all duration-300 relative group`}
          >
            <div className="absolute top-2 left-2 text-sm text-cyan-300 font-mono bg-black/50 px-2 py-1 rounded z-10">
              {feed.label}
            </div>
            <img
              src={feed.fake}
              alt={feed.label}
              className="w-full h-60 object-cover rounded-lg opacity-90 group-hover:opacity-100 transition duration-300"
            />
          </div>
        ))}
      </div>
    </div>
  );
}
